export class DnsRecord {
  constructor({ hostname, type, value, createdAt }) {
    this.hostname = hostname;
    this.type = type;
    this.value = value;
    this.createdAt = createdAt;
  }

  toResponse() {
    return {
      hostname: this.hostname,
      type: this.type,
      value: this.value,
      createdAt: this.createdAt.toISOString(),
    };
  }
}

export class DnsStore {
  constructor() {
    this._records = new Map();
    this._rrCursor = new Map();
  }

  listFor(hostname) {
    return [...(this._records.get(hostname) ?? [])];
  }

  add(record) {
    const existing = this._records.get(record.hostname);
    if (existing) {
      existing.push(record);
    } else {
      this._records.set(record.hostname, [record]);
    }
    return record;
  }

  delete(hostname, recordType, value) {
    const records = this._records.get(hostname);
    if (!records) {
      return null;
    }

    const index = records.findIndex(
      (record) => record.type === recordType && record.value === value,
    );
    if (index === -1) {
      return null;
    }

    const [removed] = records.splice(index, 1);
    if (records.length === 0) {
      this._records.delete(hostname);
      this._rrCursor.delete(hostname);
    }
    return removed;
  }

  /**
   * Rotate an A-record RRset the way many resolvers do for successive queries.
   * Listing records does not call this; only resolve does.
   */
  rotateIps(hostname, ips) {
    if (ips.length <= 1) {
      return ips;
    }
    const cursor = this._rrCursor.get(hostname) ?? 0;
    const offset = cursor % ips.length;
    this._rrCursor.set(hostname, offset + 1);
    return ips.slice(offset).concat(ips.slice(0, offset));
  }

  clear() {
    this._records.clear();
    this._rrCursor.clear();
  }
}

/**
 * In-process FIFO job queue.
 *
 * `enqueue` is synchronous and never waits on a worker, so resolve
 * can fire-and-forget `query.log` work without adding latency.
 * A background worker calls `dequeue`, which sleeps until a job is ready.
 */
export class JobQueue {
  constructor({ maxSize = 10_000 } = {}) {
    this.maxSize = maxSize;
    this.ready = [];
    this.waiters = [];
    this._nextId = 1;
    this.enqueued = 0;
    this.dequeued = 0;
    this.dropped = 0;
  }

  get size() {
    return this.ready.length;
  }

  /**
   * @param {string} type
   * @param {object} [payload]
   * @param {{ dropIfFull?: boolean }} [options]
   * @returns {object | null} the job, or null if dropped under backpressure
   */
  enqueue(type, payload = {}, { dropIfFull = false } = {}) {
    if (dropIfFull && this.size >= this.maxSize) {
      this.dropped += 1;
      return null;
    }

    const job = {
      id: this._nextId++,
      type,
      payload,
      enqueuedAt: Date.now(),
    };

    this.enqueued += 1;
    this._deliver(job);
    return job;
  }

  /**
   * Wait for the next job. Resolves with `null` when `signal` aborts
   * or `close()` is called.
   */
  dequeue(signal) {
    if (this.ready.length > 0) {
      this.dequeued += 1;
      return Promise.resolve(this.ready.shift());
    }
    if (signal?.aborted) {
      return Promise.resolve(null);
    }

    return new Promise((resolve) => {
      let settled = false;
      const finish = (job) => {
        if (settled) {
          return;
        }
        settled = true;
        signal?.removeEventListener("abort", onAbort);
        if (job) {
          this.dequeued += 1;
        }
        resolve(job);
      };

      const onJob = (job) => finish(job);
      const onAbort = () => {
        const index = this.waiters.indexOf(onJob);
        if (index !== -1) {
          this.waiters.splice(index, 1);
        }
        finish(null);
      };

      this.waiters.push(onJob);
      signal?.addEventListener("abort", onAbort, { once: true });
      if (signal?.aborted) {
        onAbort();
      }
    });
  }

  stats() {
    return {
      ready: this.ready.length,
      enqueued: this.enqueued,
      dequeued: this.dequeued,
      dropped: this.dropped,
    };
  }

  close() {
    const waiters = this.waiters.splice(0);
    for (const waiter of waiters) {
      waiter(null);
    }
  }

  _deliver(job) {
    const waiter = this.waiters.shift();
    if (waiter) {
      waiter(job);
    } else {
      this.ready.push(job);
    }
  }
}

export function createJobHandlers({ queryLogs } = {}) {
  return {
    "query.log": async (job) => {
      queryLogs.append(job.payload);
    },
  };
}

